import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    n = int(next(iterator))
    m = int(next(iterator))

    ops = []
    for _ in range(n):
        t = int(next(iterator))
        x_prime = int(next(iterator))
        y = int(next(iterator))
        x = x_prime / 100000.0
        ops.append((t, x, y))

    min_time = [-1] * (m + 1)
    min_time[0] = 0

    current_reachable = {0}

    for step_idx, (t, x, y) in enumerate(ops):
        step_num = step_idx + 1
        new_reachable = set()

        if t == 1:
            for k in current_reachable:
                for a in range(y + 1):
                    val = k
                    for _ in range(a):
                        val = int((val + x) // 1 + (1 if (val + x) % 1 > 0 else 0))
                        if val > m:
                            break
                    if val <= m:
                        new_reachable.add(val)
                        if min_time[val] == -1:
                            min_time[val] = step_num
        else:
            for k in current_reachable:
                for a in list(range(y + 1)):
                    val = k
                    for _ in range(a):
                        if val == 0:
                            val = int((val * x) // 1 + (1 if (val * x) % 1 > 0 else 0))
                            break
                        val = int((val * x) // 1 + (1 if abs((val * x) % 1) > 1e-9 else 0))
                        if val > m:
                            break
                        if val == k and a > 0:
                            break
                    if val <= m:
                        new_rereachable = new_reachable | {val}
                        if min_time[val] == -1:
                            min_time[step_num] = step_num

        current_reachable.update(new_reachable)

    print(*(min_time[1:m+1]))

if __name__ == "__main__":
    solve()
